"use strict";(globalThis.webpackChunkblog_2=globalThis.webpackChunkblog_2||[]).push([[9631],{73230(l){l.exports=JSON.parse('{"tag":{"label":"LLM","permalink":"/blog/docs/tags/llm","allTagsPath":"/blog/docs/tags","count":9,"items":[{"id":"llm-learning/day-02-embedding","title":"Embedding","description":"Token \u628a\u6587\u672c\u5207\u6210\u6a21\u578b\u53ef\u5904\u7406\u7684\u5355\u4f4d\uff0c\u4f46\u6a21\u578b\u8fd8\u9700\u8981\u7528\u6570\u503c\u5904\u7406\u8fd9\u4e9b\u5355\u4f4d\u3002\u7ed9\u6587\u6863\u7ad9\u52a0\u641c\u7d22\u65f6\uff0c\u7528\u6237\u8f93\u5165\\"\u600e\u4e48\u5904\u7406\u8bf7\u6c42\u8d85\u65f6\\"\uff0c\u4e0d\u4e00\u5b9a\u4f1a\u5199\u51fa\u6587\u6863\u91cc\u7684\\"\u7f51\u7edc\u9519\u8bef\\"\u3002Embedding \u662f\u5904\u7406\u8fd9\u7c7b\u8868\u8fbe\u63a5\u8fd1\u3001\u7528\u8bcd\u4e0d\u540c\u7684\u68c0\u7d22\u9700\u6c42\u7684\u4e00\u79cd\u8868\u793a\u65b9\u6cd5\u3002","permalink":"/blog/docs/llm-learning/day-02-embedding"},{"id":"llm-learning/day-07-prompt","title":"Prompt \u5de5\u7a0b","description":"\u77e5\u9053 Token\u3001\u91c7\u6837\u548c\u4e0a\u4e0b\u6587\u7a97\u53e3\u7684\u9650\u5236\u540e\uff0c\u4e0b\u4e00\u6b65\u662f\u628a\u4efb\u52a1\u4ea4\u4ee3\u6e05\u695a\u3002\u8ba9\u6a21\u578b\\"\u5e2e\u6211\u770b\u770b\u8fd9\u6bb5\u4ee3\u7801\\"\u901a\u5e38\u5f97\u5230\u6cdb\u6cdb\u5efa\u8bae\u3002\u628a\u8bed\u8a00\u7248\u672c\u3001\u62a5\u9519\u3001\u9884\u671f\u884c\u4e3a\u548c\u8f93\u51fa\u683c\u5f0f\u8865\u9f50\uff0c\u7ed3\u679c\u624d\u66f4\u63a5\u8fd1\u4e00\u6b21\u53ef\u6267\u884c\u7684\u6392\u67e5\u3002\u7ec4\u7ec7\u8fd9\u4e9b\u8f93\u5165\u7684\u5de5\u4f5c\u5e38\u88ab\u79f0\u4e3a Prompt \u5de5\u7a0b\u3002","permalink":"/blog/docs/llm-learning/day-07-prompt"},{"id":"llm-learning/day-08-rag","title":"RAG","description":"Prompt \u80fd\u4ea4\u4ee3\u4efb\u52a1\uff0c\u4f46\u5b83\u4e0d\u80fd\u8ba9\u6a21\u578b\u51ed\u7a7a\u77e5\u9053\u4eca\u5929\u66f4\u65b0\u7684\u5185\u90e8\u89c4\u5219\u3002\u5ba2\u670d\u673a\u5668\u4eba\u9700\u8981\u56de\u7b54\\"\u9000\u6b3e\u7533\u8bf7\u9700\u8981\u54ea\u4e9b\u6750\u6599\\"\u65f6\uff0c\u628a\u89c4\u5219\u76f4\u63a5\u5bc4\u5e0c\u671b\u4e8e\u6a21\u578b\u8bb0\u5fc6\uff0c\u65e2\u96be\u66f4\u65b0\u4e5f\u96be\u8ffd\u6eaf\u3002RAG \u9002\u5408\u628a\u76f8\u5173\u8d44\u6599\u5728\u56de\u7b54\u65f6\u63d0\u4f9b\u7ed9\u6a21\u578b\u3002","permalink":"/blog/docs/llm-learning/day-08-rag"},{"id":"llm-learning/day-01-token","title":"Token \u4e0e\u5206\u8bcd","description":"LLM \u5df2\u7ecf\u8fdb\u5165\u7f16\u7801\u3001\u641c\u7d22\u548c\u81ea\u52a8\u5316\u5de5\u4f5c\u6d41\u3002\u60f3\u5224\u65ad\u4e00\u6b21\u8c03\u7528\u4e3a\u4ec0\u4e48\u6536\u8d39\u3001\u957f\u6587\u4e3a\u4ec0\u4e48\u4f1a\u5931\u8d25\uff0c\u5148\u4ece\u4eba\u7c7b\u6587\u672c\u8fdb\u5165\u6a21\u578b\u7684\u7b2c\u4e00\u5c42\u5f00\u59cb\uff1a\u6a21\u578b\u5e76\u4e0d\u76f4\u63a5\u6309\\"\u5b57\\"\u6216\\"\u5355\u8bcd\\"\u8bfb\u53d6\u8f93\u5165\uff0c\u5b83\u8bfb\u53d6\u7684\u662f Token\u3002","permalink":"/blog/docs/llm-learning/day-01-token"},{"id":"llm-learning/day-03-transformer","title":"Transformer","description":"Embedding \u5df2\u7ecf\u628a Token \u8868\u793a\u6210\u6570\u503c\uff0c\u4f46\u5355\u4e2a\u6570\u503c\u8fd8\u4e0d\u77e5\u9053\u524d\u540e\u6587\u3002\u804a\u5929\u6a21\u578b\u4e3a\u4ec0\u4e48\u80fd\u6839\u636e\u524d\u6587\u7ee7\u7eed\u5199\u4e00\u53e5\u8bdd\uff0c\u800c\u4e0d\u662f\u53ea\u770b\u6700\u540e\u4e00\u4e2a\u8bcd\uff1f\u73b0\u4ee3\u8bed\u8a00\u6a21\u578b\u5e38\u7528 Transformer \u67b6\u6784\u6765\u5904\u7406\u4e00\u6bb5 Token \u4e4b\u95f4\u7684\u5173\u7cfb\u3002","permalink":"/blog/docs/llm-learning/day-03-transformer"},{"id":"llm-learning/day-05-context-window","title":"\u4e0a\u4e0b\u6587\u7a97\u53e3","description":"\u6a21\u578b\u6309 Token \u4e00\u6b65\u6b65\u751f\u6210\u56de\u7b54\uff0c\u4f46\u4e00\u6b21\u8bf7\u6c42\u80fd\u5e26\u5165\u7684\u4e0a\u4e0b\u6587\u6709\u9650\u3002\u628a\u4e00\u4efd\u5f88\u957f\u7684\u9700\u6c42\u6587\u6863\u7c98\u8fdb\u804a\u5929\u6846\u540e\uff0c\u4e3a\u4ec0\u4e48\u6a21\u578b\u53ef\u80fd\u62d2\u7edd\u8bf7\u6c42\uff0c\u6216\u8005\u56de\u7b54\u6f0f\u6389\u524d\u9762\u7684\u6761\u4ef6\uff1f\u5148\u68c0\u67e5\u4e0a\u4e0b\u6587\u7a97\u53e3\u3002","permalink":"/blog/docs/llm-learning/day-05-context-window"},{"id":"llm-learning/overview","title":"\u4ece\u8f93\u5165\u5230\u5e94\u7528\uff1a\u6211\u600e\u6837\u7406\u89e3\u5927\u6a21\u578b","description":"Cursor\u3001Claude Code \u548c\u5404\u79cd\u804a\u5929\u52a9\u624b\u5df2\u7ecf\u8fdb\u5165\u65e5\u5e38\u5f00\u53d1\u3002\u5bf9 IT \u4ece\u4e1a\u8005\u6765\u8bf4\uff0c\u4e0d\u4e00\u5b9a\u8981\u81ea\u5df1\u8bad\u7ec3\u6a21\u578b\uff0c\u4f46\u81f3\u5c11\u8981\u77e5\u9053\uff1a\u4e00\u6bb5\u6587\u5b57\u600e\u6837\u53d8\u6210\u6a21\u578b\u80fd\u5904\u7406\u7684\u8f93\u5165\uff0c\u6a21\u578b\u4e3a\u4ec0\u4e48\u4f1a\u7b54\u9519\uff0c\u4ee5\u53ca\u600e\u6837\u4e3a\u56de\u7b54\u8865\u5145\u5916\u90e8\u8d44\u6599\u3002","permalink":"/blog/docs/llm-learning/overview"},{"id":"\u5de5\u7a0b\u5b9e\u8df5/resume-workspace-ai","title":"\u505a\u4e86\u4e00\u4e2a\u672c\u5730\u90e8\u7f72\u7684AI \u7b80\u5386\u5de5\u4f5c\u53f0","description":"\u6700\u521d\u6211\u53ea\u60f3\u505a\u4e00\u4e2a\u80fd\u7f16\u8f91\u3001\u9884\u89c8\u5e76\u6253\u5370 A4 \u7b80\u5386\u7684\u9875\u9762\u3002\u505a\u5b8c\u57fa\u7840\u7248\u540e\uff0c\u8fd8\u60f3\u8ba9AI\u5e2e\u6211\u4f18\u5316\u7b80\u5386\uff0c\u518d\u8ba9\u5b83\u5e2e\u6211\u770b\u770b\u6709\u4ec0\u4e48\u53ef\u4ee5\u4f18\u5316\u548c\u6269\u5c55\u7684\u5730\u65b9\uff0c\u5c31\u6210\u73b0\u5728\u7684\u6548\u679c\u3002","permalink":"/blog/docs/\u5de5\u7a0b\u5b9e\u8df5/resume-workspace-ai"},{"id":"llm-learning/day-06-probability","title":"\u6982\u7387\u4e0e\u91c7\u6837","description":"Transformer \u548c Attention \u5904\u7406\u5b8c\u5f53\u524d\u4e0a\u4e0b\u6587\u540e\uff0c\u8fd8\u8981\u51b3\u5b9a\u8f93\u51fa\u4ec0\u4e48\u3002\u4e3a\u4ec0\u4e48\u540c\u4e00\u4e2a\u63d0\u793a\u8bcd\u6709\u65f6\u5f97\u5230\u4e0d\u540c\u63aa\u8f9e\uff0c\u6709\u65f6\u53c8\u51e0\u4e4e\u5b8c\u5168\u4e00\u81f4\uff1f\u751f\u6210\u6a21\u578b\u5728\u6bcf\u4e00\u6b65\u4f1a\u4e3a\u4e0b\u4e00\u4e2a Token \u7ed9\u51fa\u5019\u9009\u5206\u6570\uff0c\u91c7\u6837\u8bbe\u7f6e\u51b3\u5b9a\u600e\u6837\u4ece\u5019\u9009\u4e2d\u9009\u62e9\u3002","permalink":"/blog/docs/llm-learning/day-06-probability"}],"unlisted":false}}')}}]);